INSERT INTO `setting_general` (`id_setting_general`, `title_page`, `kata_kunci`, `deskripsi`, `author`, `alamat_bisnis`, `email_bisnis`, `telepon_bisnis`, `favicon`, `logo`, `base_url`, `landing_page_url`, `script_pesan`, `konten_landing_page`) VALUES
(1, 'Adi & Tari', 'Aplikasi Undangan Digital', 'Aplikasi untuk mengelola undangan digital', 'Solihul Hadi', 'Jalan RE Martadinata No 108 Ancaran Kuningan', 'dhiforester@gmail.com', '0232876240', '1adf3d885dbf60af05204208a2a328.png', '7eba2d84868075b73dd6bbb82403f4.png', 'http://localhost:81/Weding/admin.weding/', 'http://localhost:81/Weding/app.weding/', 'Assalamuaaikum%20Wr%20Wb.%0AKami%20mengundang%20bapak%2Fibu%20dalam%20acara%20pernikahan%20kami%20yang%20insyaalloh%20akan%20dilaksanakan%20pada%0AHari%20%3A%20Minggu%0ATanggal%20%3A%2029%20September%202024%0ATempat%20%3A%20Mayang%20Catering%20Kuningan%0ABesar%20harapan%20kami%20agar%20anda%20dapat%20hadir%20dalam%20acara%20tersebut', '{\r\n  \"page_1\": {\r\n    \"title\": \"Adi & Tari\",\r\n    \"subtitle\": \"Dengan Segala Kerendahan Hati, Kami Mohon Doa Restu\",\r\n    \"weding_date\": \"2024-09-29\",\r\n    \"background\": \"page_1.png\"\r\n  },\r\n  \"page_2\": {\r\n    \"title\": \"Assalamualaikum Wr Wb\",\r\n    \"subtitle_1\": \"Dengan penuh rasa syukur dan kebahagiaan, kami mengundang Anda untuk hadir pada acara pernikahan kami \",\r\n    \"subtitle_2\": \"Kami sangat berharap kehadiran Anda dapat menambah kebahagiaan dan meriahkan momen istimewa ini. Semoga Allah memberkati dan melimpahkan rahmat-Nya kepada kita semua.\",\r\n    \"male_name\": \"Adi Fuji Stiadi\",\r\n    \"male_desciption\": \"Putra dari Bapak E Mahfud (Alm) dan Ibu Sukmawati (Alm).\",\r\n    \"male_foto\": \"male.png\",\r\n    \"female_name\": \"Siti Lestari\",\r\n    \"female_desciption\": \"Putri dari Bapak Suwarno dan Ibu Tarsih\",\r\n    \"female_foto\": \"female.png\"\r\n  },\r\n  \"page_3\": {\r\n    \"title\": \"Akad & Resepsi\",\r\n    \"subtitle\": \"Waktu dan Tempat Acara\",\r\n    \"event_title_1\": \"Akad Nikah\",\r\n    \"event_start_1\": \"08:00\",\r\n    \"event_end_1\": \"09:00\",\r\n    \"event_daydate_1\": \"Minggu, 29/09/24\",\r\n    \"event_place_1\": \"Jl. RE. Martadinata No.176, Ciporang Kuningan\",\r\n    \"event_title_2\": \"Resepsi\",\r\n    \"event_start_2\": \"09:00\",\r\n    \"event_end_2\": \"15:00\",\r\n    \"event_daydate_2\": \"Minggu, 29/09/24\",\r\n    \"event_place_2\": \"Bell Room Mayang Catering\",\r\n    \"background\": \"page_3.png\"\r\n  },\r\n  \"page_4\": {\r\n    \"title\": \"Segenap Keluarga\",\r\n    \"subtitle\": \"Pernikahan yang bahagia adalah menyatunya dua insan yang bersedia saling mengerti, memahami, dan saling memaafkan\",\r\n    \"group_1\": {\r\n      \"title\":\"E Mahfud., Alm\",\r\n      \"subtitle\":\"Janganlah engkau menuntut pasanganmu untuk sempurna, tapi sempurnakanlah dirimu agar engkau mampu menutupi kekurangannya.\",\r\n      \"image\":\"group_1.png\"\r\n    },\r\n    \"group_2\": {\r\n      \"title\":\"Sukmawati., Alm\",\r\n      \"subtitle\":\"Dunia ini adalah perhiasan dan sebaik-baik perhiasannya adalah perempuan yang shalihah.\",\r\n      \"image\":\"group_2.png\"\r\n    },\r\n    \"group_3\": {\r\n      \"title\":\"Suwarno\",\r\n      \"subtitle\":\"Tidak ada cinta antara dua jiwa yang lebih besar daripada cinta antara pasangan.\",\r\n      \"image\":\"group_3.jpg\"\r\n    },\r\n    \"group_4\": {\r\n      \"title\":\"Tarsih\",\r\n      \"subtitle\":\"Ketika sepasang suami istri memandang dengan cinta, Allah memandang mereka dengan belas kasihan.\",\r\n      \"image\":\"group_4.jpg\"\r\n    }\r\n  }\r\n}');
INSERT INTO `testimoni` (`id`, `nama`, `pesan`, `datetime`, `status`) VALUES
(5, 'Santi Nursari', 'Selamat menempuh hidup baru! Semoga perjalanan kalian dipenuhi dengan cinta, kebahagiaan, dan kesuksesan. Dalam setiap langkah yang kalian ambil, semoga selalu ada saling pengertian dan dukungan yang tak pernah pudar. Selamat berbahagia!', '2024-09-18 16:50:02', 'Publish'),
(6, 'Solihul Hadi', 'Di hari bahagia ini, aku ingin mengucapkan selamat kepada kalian berdua. Semoga cinta dan kebahagiaan yang kalian rasakan hari ini akan terus berkembang dan memperkuat hubungan kalian seiring berjalannya waktu. Selamat berbahagia dan selamat membangun masa depan yang indah bersama', '2024-09-18 16:50:17', 'Publish'),
(7, 'Aruna Parasilva Nursari', 'Cinta sejati adalah ketika kita menemukan seseorang yang mampu membuat kita merasa lengkap dan diterima apa adanya. Selamat menempuh perjalanan baru bersama pasanganmu, semoga setiap hari penuh dengan kebahagiaan, cinta, dan pengertian yang mendalam.', '2024-09-18 16:50:34', 'Publish'),
(8, 'Suwarno', 'Di hari istimewa ini, aku berdoa agar setiap detik yang kalian lewati bersama menjadi momen berharga yang penuh dengan kebahagiaan. Semoga kalian selalu menemukan kekuatan dalam kebersamaan dan terus saling mendukung dalam setiap fase kehidupan.', '2024-09-18 16:50:48', 'Publish'),
(9, 'Tarsih', 'Semoga pernikahan ini menjadi awal dari sebuah cerita indah yang penuh dengan kebahagiaan dan kedamaian. Selamat untuk kedua mempelai, semoga cinta kalian terus tumbuh dan berkembang, serta menghadapi segala tantangan dengan penuh kepercayaan dan kasih sayang', '2024-09-18 16:50:57', 'Publish');
